// Deterministic guardrails AFTER the LLM. The model proposes, these rules decide.
const src = $('Injection pre-check (rules)').item.json;
const q = $json.output || null;
const flags = [];
let error = null;
if (!q) { error = $json.error?.message || $json.error || 'No valid structured output'; flags.push('Model error'); }
const norm = s => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
const hay = norm(src.title + ' ' + src.text);
const evidence = (q?.evidence || []).filter(e => e && norm(e).length >= 8 && hay.includes(norm(e)));
const dropped = (q?.evidence || []).length - evidence.length;
if (dropped > 0) flags.push('Evidence dropped');
let score = q ? Math.max(0, Math.min(3, Number(q.icp_score) || 0)) : null;
if (q && !q.is_funding_announcement) score = 0;            // rule beats model
if (q && evidence.length === 0 && score >= 2) score = 1;   // no grounded evidence → never Qualified
if (q && q.amount_eur && q.amount_eur > 50e6 && score > 1) score = 1; // too large for ICP
const status = error ? 'New' : score >= 2 ? 'Qualified' : 'Archived';
const tokensEst = Math.round((src.title.length + src.text.length + 3500) / 4) + 200; // prompt+schema+output, rough
return { json: { ...src, q, evidence, droppedEvidence: dropped, score, status, flags, error, tokensEst } };

const cfg = $json.cfg;
const t = s => [{ type: 'text', text: { content: String(s ?? '').slice(0, 1900) } }];
const q = $json.q || {};
const countryMap = { DE:'DE', AT:'AT', CH:'CH', NL:'NL', GB:'UK', UK:'UK' };
const EU = ['FR','ES','IT','PT','BE','LU','IE','DK','SE','FI','PL','CZ','EE','LV','LT','SK','SI','HR','RO','BG','HU','GR','CY','MT'];
const c = (q.country || '').toUpperCase();
const country = countryMap[c] || (EU.includes(c) ? 'Other EU' : c ? 'Non-EU' : null);
const rounds = { 'pre-seed':'Pre-seed', 'seed':'Seed', 'series a':'Series A', 'series b':'Series B' };
const round = q.round ? (rounds[q.round.toLowerCase()] || 'Later') : 'Unknown';
const props = {
  'Company': { title: t(q.company || $json.title) },
  'Status': { status: { name: $json.status } },
  'Signal': { select: { name: 'Funding' } },
  'Signal source': { url: $json.link },
  'Signal summary': { rich_text: t(`${$json.title} (${$json.source})`) },
  'Signal date': { date: { start: $json.published } },
  'Dedupe key': { rich_text: t($json.link) },
  'Qualify reasons': { rich_text: t($json.error ? `ERROR: ${$json.error}` : `${q.reasons || ''} | dach_link: ${q.dach_link}`) },
  'Evidence': { rich_text: t($json.evidence.map(e => `"${e}"`).join('\n')) },
  'Round': { select: { name: round } },
  'Sector': { rich_text: t(q.sector || '') },
  'Flags': { multi_select: $json.flags.map(name => ({ name })) },
  'Prompt version': { rich_text: t(cfg.promptVersion) }
};
if ($json.score !== null) props['ICP score'] = { number: $json.score };
if (q.amount_eur) props['Amount EUR'] = { number: q.amount_eur };
if (q.website && /^https?:\/\//.test(q.website)) props['Domain'] = { url: q.website };
if (country) props['Country'] = { select: { name: country } };
return { json: { ...$json, notionBody: { parent: { database_id: cfg.notionCompaniesDb }, properties: props } } };

// Contract back to the orchestrator: small, explicit, no raw article text except for people extraction.
const b = $('Build company page').item.json;
const ok = $json.object === 'page';
return { json: {
  ok, companyPageId: ok ? $json.id : null, company: b.q?.company || b.title,
  score: b.score, status: b.status, flags: b.flags, error: ok ? b.error : (b.error || $json.message || 'Notion write failed'),
  tokensEst: b.tokensEst, droppedEvidence: b.droppedEvidence,
  link: b.link, title: b.title, text: b.text, cfg: b.cfg
}};
